window.AUTH=window.AUTH||{};window.AUTH["10-1211"]={"d":"10-1211","id":"2011/10-1211","n":"Vartelas v. Holder","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the respondent","date":"","url":"https://www.justice.gov/osg/media/196816/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/vartelas-v-holder-brief-merits","n":96}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep566/usrep566257/usrep566257.pdf","tr":true,"items":[{"t":"case","label":"Atkinson v. Attorney Gen.","cite":"479 F.3d 222","y":2007,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/479/222/","by":{"0":"34"}},{"t":"case","label":"Bugajewitz v. Adams","cite":"228 U.S. 585","y":1913,"id":"scdb/1912-191","sc":1,"sum":"Congress has power to order the deportation of aliens whose presence in the country it deems hurtful; and this applies to prostitutes regardless of the time they have been here.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"California Dep’t of Corr. v. Morales","cite":"514 U.S. 499","y":1995,"id":"1994/93-1462","sc":1,"sum":"The amendment's application to prisoners who committed their crimes before it was enacted does not violate the Ex Post Facto Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Camins v. Gonzales","cite":"500 F.3d 872","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/500/872/","op":1,"by":{"0":"6, 8"}},{"t":"case","label":"Carlson v. Landon","cite":"342 U.S. 524","y":1952,"id":"scdb/1951-054","sc":1,"sum":"1. Under § 20 (a) of the Immigration Act, as amended by § 23 of the Internal Security Act, the Attorney General may, in his discretion, hold in custody without bail, pending determination as to their deportability, aliens who are members of the Communist Party of the United States, when there is reasonable cause to believe that their release on bail would endanger the safety and welfare of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Chew Heong v. United States","cite":"112 U.S. 536","y":1884,"id":"scdb/1884-059","sc":1,"op":1,"sum":"The fourth section of the act of Congress, approved May 6,1882, ch. 126, as amended by the act of July 5, 1884, ch. 120, prescribing the certificate which shall be produced by a Chinese laborer as the “only evidence permissible to establish his right of re-entry” into the United States, is not applicable to Chinese laborers who, residing in this country at the date of the.treaty of-November 17,1880, departed by sea …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Collins v. Youngblood","cite":"497 U.S. 37","y":1990,"id":"1989/89-742","sc":1,"sum":"Respondent was convicted in a Texas state court of aggravated sexual abuse and sentenced to life imprisonment and a $10,000 fine. After his conviction and sentence were affirmed on direct appeal, he applied for a writ of habeas corpus in state court, arguing that Texas law did not authorize both a fine and prison term for his offense, and thus that his judgment and sentence were void and he was entitled to a new …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 19, 20"}},{"t":"case","label":"Cox v. Hart","cite":"260 U.S. 427","y":1922,"id":"scdb/1922-054","sc":1,"sum":"1. What will constitute possession of a tract of land depends largely upon its character and condition and the use to which it is adapted; enclosure, or physical occupancy of every part, is not necessary.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Dabone v. Karn","cite":"763 F.2d 593","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/763/593/","sum":"Rejecting an alien’s Fleuti argument and noting the “the numerous trips he made in and out of the United States”.","sumSrc":"brief:0","by":{"0":"25"}},{"t":"case","label":"Dias v. INS","cite":"311 F.3d 456","y":2002,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/311/456/","by":{"0":"33"}},{"t":"case","label":"Doe v. Attorney Gen.","cite":"659 F.3d 266","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/659/266/","by":{"0":"28"}},{"t":"case","label":"Ferguson v. United States Att’y Gen.","cite":"563 F.3d 1254","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/563/1254/","by":{"0":"34"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"op":3,"ar":3,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Harisiades v. Shaughnessy","cite":"342 U.S. 580","y":1952,"id":"scdb/1951-056","sc":1,"ar":1,"by":{"0":"17, 21, 22"}},{"t":"case","label":"Heitland v. INS","cite":"551 F.2d 495","y":1977,"url":"https://www.courtlistener.com/c/F.2d/551/495/","by":{"0":"24"}},{"t":"case","label":"Hem v. Maurer","cite":"458 F.3d 1185","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/458/1185/","by":{"0":"33"}},{"t":"case","label":"Hernandez-Castillo v. Moore","cite":"436 F.3d 516","y":2006,"url":"https://www.courtlistener.com/c/F.3d/436/516/","by":{"0":"33"}},{"t":"case","label":"Hughes Aircraft Co. v. United States ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"op":5,"ar":3,"sum":"The Court held that, because the 1986 amendment does not apply retroactively to qui tam suits regarding allegedly false claims submitted prior to its enactment, Schumer's action should have been dismissed, as required by the pre-1986 version of the FCA.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40"}},{"t":"case","label":"INS v. Lopez-Mendoza","cite":"468 U.S. 1032","y":1984,"id":"1983/83-491","sc":1,"sum":"In both criminal and civil proceedings, the \"body\" or identity of a defendant is never suppressible as fruit of an illegal arrest. This alone was sufficient basis to uphold Lopez-Mendoza's deportation order. Moreover, deportation proceedings are civil actions and the protections afforded defendants in the criminal context do not apply.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"INS v. National Ctr. for Immigrants’ Rights, Inc.","cite":"502 U.S. 183","y":1991,"id":"1991/90-1090","sc":1,"sum":"The regulation on its face is consistent with the Attorney General's statutory authority.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":7,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Jurado-Gutierrez v. Greene","cite":"190 F.3d 1135","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/190/1135/","by":{"0":"27"}},{"t":"case","label":"Kellermann v. Holder","cite":"592 F.3d 700","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/592/700/","by":{"0":"33"}},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"sum":"The Court held that the First Amendment did not obligate Kleindienst to grant a waiver to Mandel.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"op":14,"ar":16,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim"}},{"t":"case","label":"Landon v. Plasencia","cite":"459 U.S. 21","y":1982,"id":"1982/81-129","sc":1,"op":1,"sum":"Section 235 of the Immigration and Nationality Act of 1952 (Act) permits the Immigration and Naturalization Service (INS) to examine \"all aliens\" who seek \"admission or readmission to\" the United States and empowers immigration officers to take evidence concerning the privilege of any persons suspected of being an alien \"to enter, reenter, pass through, or reside\" in the United States, and to detain for further …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 21"}},{"t":"case","label":"Leng May Ma v. Barber","cite":"357 U.S. 185","y":1958,"id":"1957/105","sc":1,"sum":"Her release on parole did not alter her status as an excluded alien; she was not \"within the United States,\" within the meaning of § 243 (h); and thus she was not eligible for the benefits of that section. Pp. 185-190. 241 F. 2d 85, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2"}},{"t":"case","label":"Lindsey v. Washington","cite":"301 U.S. 397","y":1937,"id":"scdb/1936-123","sc":1,"sum":"A state statute making more onerous the standard of punishment is ex post facto and void as applied to a crime committed before its enactment. P.:401. Under the law of the State of Washington at the time of the alleged offense, imprisonment of the accused could have been fixed by the judge at less than the maximum of 15 years. By the law as amended and applied (c. 114, L. Wash., 1935), sentence for 15 years was made …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Lovan v. Holder","cite":"574 F.3d 990","y":2009,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/574/990/","by":{"0":"34"}},{"t":"case","label":"Lozano-Giron v. INS","cite":"506 F.2d 1073","y":1974,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/506/1073/","by":{"0":"25"}},{"t":"case","label":"Mahler v. Eby","cite":"264 U.S. 32","y":1924,"id":"scdb/1923-058","sc":1,"sum":"1. The inhibition of ex post facto laws, (Const. Art. I, § 9) applies only to criminal laws, and not to a law for deporting aliens who by conviction of crime are shown to be undesirable as residents of this country.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Martin v. Hadix","cite":"527 U.S. 343","y":1999,"id":"1998/98-262","sc":1,"op":1,"ar":1,"sum":"The Court held that the Prison Litigation Reform Act of 1995 \"limits attorney's fees for post-judgment monitoring services performed after the PLRA's effective date, but does not limit fees for monitoring performed before that date.\" \"To impose the new standards now, for work performed before the PLRA became effective, would upset the reasonable expectations of the parties,\" Justice O'Connor wrote for the Court.","sumSrc":"Oyez","by":{"0":"8, 13, 26, 38"}},{"t":"case","label":"Mbea v. Gonzales","cite":"482 F.3d 276","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/482/276/","by":{"0":"33"}},{"t":"case","label":"Miller v. Florida","cite":"482 U.S. 423","y":1987,"id":"1986/86-5344","sc":1,"sum":"Application of the revised guidelines law to petitioner, whose crimes occurred before the law's effective date, violates the Ex Post Facto Clause of Article I of the Federal Constitution. The revised law evidences all of the elements necessary to bring it within the ex post facto prohibition.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Odoku v. INS","cite":"276 Fed. Appx. 21","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./276/21/","by":{"0":"28"}},{"t":"case","label":"Olatunji v. Ashcroft","cite":"387 F.3d 383","y":2004,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/387/383/","op":3,"by":{"0":"8"}},{"t":"case","label":"Pearsall v. Great Northern Ry.","cite":"161 U.S. 646","y":1896,"id":"scdb/1895-167","sc":1,"sum":"In 1856, the Minneapolis and St. Cloud Railroad Company was incorporated by the legislature of the Territory of Minnesota, with authority to construct a railroad on an indicated route, and to connect its road by branches with any other road in the Territory, or to become part owner or lessee of any railroad in said Territory; and also “to connect with any railroad running in the same direction with this road, and …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"Rankine v. Reno","cite":"319 F.3d 93","y":2003,"url":"https://www.courtlistener.com/c/F.3d/319/93/","by":{"0":"33"}},{"t":"case","label":"Republic of Austria v. Altmann","cite":"541 U.S. 677","y":2004,"id":"2003/03-13","sc":1,"op":1,"ar":2,"sum":"In a 6-to-3 decision written by Justice John Paul Stevens, the Court ruled that, while the Foreign Sovereign Immunities Act of 1976 does not explicitly state that it should be applied to actions that took place before its passage, there are strong indications in the text of the statute that Congress intended it to apply retroactively.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Rosenberg v. Fleuti","cite":"374 U.S. 449","y":1963,"id":"1962/248","sc":1,"op":4,"ar":2,"sum":"Respondent is an alien who was admitted to this country for permanent residence in 1952 and has been here continuously since, except for a visit of \"about a couple hours\" duration to Ensenada, Mexico, in 1956. After administrative proceedings, he was ordered deported on the ground that, at the time of his return in 1956, he wa \"afflicted with psychopathic personality,\" within the meaning of § 212 (a) (4) of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 10, 16, 24, 25"}},{"t":"case","label":"Saravia-Paguada v. Gonzales","cite":"488 F.3d 1122","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/488/1122/","by":{"0":"33"}},{"t":"case","label":"Society for the Propagation of the Gospel v. Wheeler","cite":"22 F. Cas. 756","y":1814,"court":"C.C.D.N.H.","url":"https://www.courtlistener.com/c/F.%20Cas./22/756/","op":1,"by":{"0":"14, 21"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"St. Cyr v. INS","cite":"229 F.3d 406","y":2000,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/229/406/","sum":"Rejecting the proposition that “aliens might have decided not to commit * * * crimes, or might have resisted conviction more vigorously, had they known that if they were not only imprisoned but also, when their prison term ended, ordered deported, they could not ask for a discretionary waiver of deportation”.","sumSrc":"brief:0","by":{"0":"27"}},{"t":"case","label":"Tineo v. Ashcroft","cite":"350 F.3d 382","y":2003,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/350/382/","by":{"0":"38"}},{"t":"case","label":"United States v. Brown","cite":"555 F.2d 407","y":1977,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/555/407/","op":2,"by":{"0":"18"}},{"t":"case","label":"United States v. Campanale","cite":"518 F.2d 352","y":1975,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/518/352/","op":2,"by":{"0":"18"}},{"t":"case","label":"United States v. De Horta Garcia","cite":"519 F.3d 658","y":2008,"url":"https://www.courtlistener.com/c/F.3d/519/658/","by":{"0":"33"}},{"t":"case","label":"United States v. Hemmings","cite":"258 F.3d 587","y":2001,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/258/587/","op":1,"by":{"0":"19"}},{"t":"case","label":"United States ex rel. Kaloudis v. Shaughnessy","cite":"180 F.2d 489","y":1950,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/180/489/","by":{"0":"22"}},{"t":"case","label":"United States v. Pfeifer","cite":"371 F.3d 430","y":2004,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/371/430/","op":2,"by":{"0":"19"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"United States ex rel. Volpe v. Smith","cite":"289 U.S. 422","y":1933,"id":"scdb/1932-085","sc":1,"op":1,"by":{"0":"3"}},{"t":"case","label":"Weaver v. Graham","cite":"450 U.S. 24","y":1981,"id":"1980/79-5780","sc":1,"sum":"Held.: A Florida statute repealing an earlier statute and reducing the amount of \"gain time\" for good conduct and obedience to prison rules deducted from a convicted prisoner's sentence is unconstitutional as an ex post facto law as applied to petitioner, whose crime was committed before the statute's enactment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"const","label":"Article I, Section 9","clauses":[["migration-importation","Migration or Importation Clause (Slave Trade)"],["habeas","Suspension Clause (Habeas Corpus)"],["attainder-ex-post-facto","Bills of Attainder and Ex Post Facto Laws"],["direct-taxes","Direct Tax Clause"],["export-clause","Export Clause"],["port-preference","Port Preference Clause"],["appropriations","Appropriations Clause"],["emoluments","Emoluments Clauses"]],"by":{"0":"17, 18, 22"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"23"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(13)(1994)","(a)(13)","(a)(13)(A)","(a)(13)(A)(v)","(a)(13)(C)","(a)(13)(C)(ii)","(a)(13)(C)(iii)","(a)(13)(C)(v)","(a)(13)(C)(vi)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"2, 38, passim, passim, 4, 16, 40, 30, passim, 29, 39, 16, passim, 39"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)(i)","(a)(2)(A)(i)(I)","(a)(2)(C)(ii)","(a)(3)","(a)(4)","(a)(6)(C)","(a)(9)(C)","(c)(1994)","(h)","(h)(1)(B)"],"stext":{"head":"§1182. Inadmissible aliens","paras":[[0,"(a) Classes of aliens ineligible for visas or admission"],[0,"Except as otherwise provided in this chapter, aliens who are inadmissible under the following paragraphs are ineligible to receive visas and ineligible to be admitted to the United States:"],[0,"(1) Health-related grounds"],[0,"(A) In general"],[2,"Any alien—"],[3,"(i) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to have a communicable disease of public health significance; 1"],[3,"(ii) except as provided in subparagraph (C), who seeks admission as an immigrant, or who seeks adjustment of status to the status of an alien lawfully admitted for permanent residence, and who has failed to present documentation of having received vaccination against vaccine-preventable diseases, which shall include at least the following diseases: mumps, measles, rubella, polio, tetanus and diphtheria toxoids, pertussis, influenza type B and hepatitis B, and any other vaccinations against vaccine-preventable diseases recommended by the Advisory Committee for Immunization Practices,"],[3,"(iii) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services in consultation with the Attorney General)—"],[4,"(I) to have a physical or mental disorder and behavior associated with the disorder that may pose, or has posed, a threat to the property, safety, or welfare of the alien or others, or"],[4,"(II) to have had a physical or mental disorder and a history of behavior associated with the disorder, which behavior has posed a threat to the property, safety, or welfare of the alien or others and which behavior is likely to recur or to lead to other harmful behavior, or"],[3,"(iv) who is determined (in accordance with regulations prescribed by the Secretary of Health and Human Services) to be a drug abuser or addict,"],[2,"is inadmissible."],[0,"(B) Waiver authorized"],[2,"For provision authorizing waiver of certain clauses of subparagraph (A), see subsection (g)."],[0,"(C) Exception from immunization requirement for adopted children 10 years of age or younger"],[2,"Clause (ii) of subparagraph (A) shall not apply to a child who—"],[3,"(i) is 10 years of age or younger,"],[3,"(ii) is described in subparagraph (F) or (G) of section 1101(b)(1) of this title; 1 and"],[3,"(iii) is seeking an immigrant visa as an immediate relative under section 1151(b) of this title,"],[2,"if, prior to the admission of the child, an adoptive parent or prospective adoptive parent of the child, who has sponsored the child for admission as an immediate relative, has executed an affidavit stating that the parent is aware of the provisions of subparagraph (A)(ii) and will ensure that, within 30 days of the child's admission, or at the earliest time that is medically appropriate, the child will receive the vaccinations identified in such subparagraph."],[0,"(2) Criminal and related grounds"],[0,"(A) Conviction of certain crimes"],[0,"(i) In general"],[3,"Except as provided in clause (ii), any alien convicted of, or who admits having committed, or who admits committing acts which constitute the essential elements of—"],[4,"(I) a crime involving moral turpitude (other than a purely political offense) or an attempt or conspiracy to commit such a crime, or"],[4,"(II) a violation of (or a conspiracy or attempt to violate) any law or regulation of a State, the United States, or a foreign country relating to a controlled substance (as defined in section 802 of title 21),"],[0,"is inadmissible."],[0,"(ii) Exception"],[3,"Clause (i)(I) shall not apply to an alien who committed only one crime if—"],[4,"(I) the crime was committed when the alien was under 18 years of age, and the crime was committed (and the alien released from any confinement to a prison or correctional institution imposed for the crime) more than 5 years before the date of application for a visa or other documentation and the date of application for admission to the United States, or"],[4,"(II) the maximum penalty possible for the crime of which the alien was convicted (or which the alien admits having committed or of which the acts that the alien admits having committed constituted the essential elements) did not exceed imprisonment for one year and, if the alien was convicted of such crime, the alien was not sentenced to a term of imprisonment in excess of 6 months (regardless of the extent to which the sentence was ultimately executed)."],[0,"(B) Multiple criminal convictions"],[2,"Any alien convicted of 2 or more offenses (other than purely political offenses), regardless of whether the conviction was in a single trial or whether the offenses arose from a single scheme of misconduct and regardless of whether the offenses involved moral turpitude, for which the aggregate sentences to confinement were 5 years or more is inadmissible."],[0,"(C) Controlled substance traffickers"],[2,"Any alien who the consular officer or the Attorney General knows or has reason to believe—"],[3,"(i) is or has been an illicit trafficker in any controlled substance or in any listed chemical (as defined in section 802 of title 21), or is or has been a knowing aider, abettor, assister, conspirator, or colluder with others in the illicit trafficking in any such controlled or listed substance or chemical, or endeavored to do so; or"],[3,"(ii) is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity,"],[2,"is inadmissible."],[0,"(D) Prostitution and commercialized vice"],[2,"Any alien who—"],[3,"(i) is coming to the United States solely, principally, or incidentally to engage in prostitution, or has engaged in prostitution within 10 years of the date of application for a visa, admission, or adjustment of status,"],[3,"(ii) directly or indirectly procures or attempts to procure, or (within 10 years of the date of application for a visa, admission, or adjustment of status) procured or attempted to procure or to import, prostitutes or persons for the purpose of prostitution, or receives or (within such 10-year period) received, in whole or in part, the proceeds of prostitution, or"],[3,"(iii) is coming to the United States to engage in any other unlawful commercialized vice, whether or not related to prostitution,"],[2,"is inadmissible."],[0,"(E) Certain aliens involved in serious criminal activity who have asserted immunity from prosecution"],[2,"Any alien—"],[3,"(i) who has committed in the United States at any time a serious criminal offense (as defined in section 1101(h) of this title),"],[3,"(ii) for whom immunity from criminal jurisdiction was exercised with respect to that offense,"],[3,"(iii) who as a consequence of the offense and exercise of immunity has departed from the United States, and"],[3,"(iv) who has not subsequently submitted fully to the jurisdiction of the court in the United States having jurisdiction with respect to that offense,"],[2,"is inadmissible."],[0,"(F) Waiver authorized"],[2,"For provision authorizing waiver of certain subparagraphs of this paragraph, see subsection (h)."],[0,"(G) Foreign government officials who have committed particularly severe violations of religious freedom"],[2,"Any alien who, while serving as a foreign government official, was responsible for or directly carried out, at any time, particularly severe violations of religious freedom, as defined in section 6402 of title 22, is inadmissible."],[0,"(H) Significant traffickers in persons"],[0,"(i) In general"],[3,"Any alien who commits or conspires to commit human trafficking offenses in the United States or outside the United States, or who the consular officer, the Secretary of Homeland Security, the Secretary of State, or the Attorney General knows or has reason to believe is or has been a knowing aider, abettor, assister, conspirator, or colluder with such a trafficker in severe forms of trafficking in persons, as defined in the section 7102 of title 22, is inadmissible."],[0,"(ii) Beneficiaries of trafficking"],[3,"Except as provided in clause (iii), any alien who the consular officer or the Attorney General knows or has reason to believe is the spouse, son, or daughter of an alien inadmissible under clause (i), has, within the previous 5 years, obtained any financial or other benefit from the illicit activity of that alien, and knew or reasonably should have known that the financial or other benefit was the product of such illicit activity, is inadmissible."],[0,"(iii) Exception for certain sons and daughters"],[3,"Clause (ii) shall not apply to a son or daughter who was a child at the time he or she received the benefit described in such clause."],[0,"(I) Money laundering"],[2,"Any alien—"],[3,"(i) who a consular officer or the Attorney General knows, or has reason to believe, has engaged, is engaging, or seeks to enter the United States to engage, in an offense which is described in section 1956 or 1957 of title 18 (relating to laundering of monetary instruments); or"],[3,"(ii) who a consular officer or the Attorney General knows is, or has been, a knowing aider, abettor, assister, conspirator, or colluder with others in an offense which is described in such section;"],[2,"is inadmissible."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1182?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1182. Inadmissible aliens","tname":"Aliens and Nationality","by":{"0":"4, 2, 30, 8, 12, 16, 30, 31, 28, 29, 3, 5, 30, 12, 30, 12, 12, 12, passim, 12, 13, 13"}},{"t":"usc","label":"8 U.S.C. § 1227","url":"https://www.law.cornell.edu/uscode/text/8/1227","subs":["(a)","(a)(2)(A)"],"by":{"0":"2, 23"}},{"t":"usc","label":"8 U.S.C. § 1229","url":"https://www.law.cornell.edu/uscode/text/8/1229","stext":{"head":"§1229. Initiation of removal proceedings","paras":[[0,"(a) Notice to appear"],[0,"(1) In general"],[1,"In removal proceedings under section 1229a of this title, written notice (in this section referred to as a \"notice to appear\") shall be given in person to the alien (or, if personal service is not practicable, through service by mail to the alien or to the alien's counsel of record, if any) specifying the following:"],[2,"(A) The nature of the proceedings against the alien."],[2,"(B) The legal authority under which the proceedings are conducted."],[2,"(C) The acts or conduct alleged to be in violation of law."],[2,"(D) The charges against the alien and the statutory provisions alleged to have been violated."],[2,"(E) The alien may be represented by counsel and the alien will be provided (i) a period of time to secure counsel under subsection (b)(1) and (ii) a current list of counsel prepared under subsection (b)(2)."],[2,"(F)(i) The requirement that the alien must immediately provide (or have provided) the Attorney General with a written record of an address and telephone number (if any) at which the alien may be contacted respecting proceedings under section 1229a of this title."],[2,"(ii) The requirement that the alien must provide the Attorney General immediately with a written record of any change of the alien's address or telephone number."],[2,"(iii) The consequences under section 1229a(b)(5) of this title of failure to provide address and telephone information pursuant to this subparagraph."],[2,"(G)(i) The time and place at which the proceedings will be held."],[2,"(ii) The consequences under section 1229a(b)(5) of this title of the failure, except under exceptional circumstances, to appear at such proceedings."],[0,"(2) Notice of change in time or place of proceedings"],[0,"(A) In general"],[2,"In removal proceedings under section 1229a of this title, in the case of any change or postponement in the time and place of such proceedings, subject to subparagraph (B) a written notice shall be given in person to the alien (or, if personal service is not practicable, through service by mail to the alien or to the alien's counsel of record, if any) specifying—"],[3,"(i) the new time or place of the proceedings, and"],[3,"(ii) the consequences under section 1229a(b)(5) of this title of failing, except under exceptional circumstances, to attend such proceedings."],[0,"(B) Exception"],[2,"In the case of an alien not in detention, a written notice shall not be required under this paragraph if the alien has failed to provide the address required under paragraph (1)(F)."],[0,"(3) Central address files"],[1,"The Attorney General shall create a system to record and preserve on a timely basis notices of addresses and telephone numbers (and changes) provided under paragraph (1)(F)."],[0,"(b) Securing of counsel"],[0,"(1) In general"],[1,"In order that an alien be permitted the opportunity to secure counsel before the first hearing date in proceedings under section 1229a of this title, the hearing date shall not be scheduled earlier than 10 days after the service of the notice to appear, unless the alien requests in writing an earlier hearing date."],[0,"(2) Current lists of counsel"],[1,"The Attorney General shall provide for lists (updated not less often than quarterly) of persons who have indicated their availability to represent pro bono aliens in proceedings under section 1229a of this title. Such lists shall be provided under subsection (a)(1)(E) and otherwise made generally available."],[0,"(3) Rule of construction"],[1,"Nothing in this subsection may be construed to prevent the Attorney General from proceeding against an alien pursuant to section 1229a of this title if the time period described in paragraph (1) has elapsed and the alien has failed to secure counsel."],[0,"(c) Service by mail"],[0,"Service by mail under this section shall be sufficient if there is proof of attempted delivery to the last address provided by the alien in accordance with subsection (a)(1)(F)."],[0,"(d) Prompt initiation of removal"],[0,"(1) In the case of an alien who is convicted of an offense which makes the alien deportable, the Attorney General shall begin any removal proceeding as expeditiously as possible after the date of the conviction."],[0,"(2) Nothing in this subsection shall be construed to create any substantive or procedural right or benefit that is legally enforceable by any party against the United States or its agencies or officers or any other person."],[0,"(e) Certification of compliance with restrictions on disclosure"],[0,"(1) In general"],[1,"In cases where an enforcement action leading to a removal proceeding was taken against an alien at any of the locations specified in paragraph (2), the Notice to Appear shall include a statement that the provisions of section 1367 of this title have been complied with."],[0,"(2) Locations"],[1,"The locations specified in this paragraph are as follows:"],[2,"(A) At a domestic violence shelter, a rape crisis center, supervised visitation center, family justice center, a victim services, or victim services provider, or a community-based organization."],[2,"(B) At a courthouse (or in connection with that appearance of the alien at a courthouse) if the alien is appearing in connection with a protection order case, child custody case, or other civil or criminal case relating to domestic violence, sexual assault, trafficking, or stalking in which the alien has been battered or subject to extreme cruelty or if the alien is described in subparagraph (T) or (U) of section 1101(a)(15) of this title."]],"more":false,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229. Initiation of removal proceedings","tname":"Aliens and Nationality","by":{"0":"2"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(e)(2)"],"by":{"0":"2, 2"}},{"t":"usc","label":"8 U.S.C. § 1229b","url":"https://www.law.cornell.edu/uscode/text/8/1229b","subs":["(a)(3)","(c)"],"stext":{"head":"§1229b. Cancellation of removal; adjustment of status","paras":[[0,"(a) Cancellation of removal for certain permanent residents"],[0,"The Attorney General may cancel removal in the case of an alien who is inadmissible or deportable from the United States if the alien—"],[1,"(1) has been an alien lawfully admitted for permanent residence for not less than 5 years,"],[1,"(2) has resided in the United States continuously for 7 years after having been admitted in any status, and"],[1,"(3) has not been convicted of any aggravated felony."],[0,"(b) Cancellation of removal and adjustment of status for certain nonpermanent residents"],[0,"(1) In general"],[1,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien—"],[2,"(A) has been physically present in the United States for a continuous period of not less than 10 years immediately preceding the date of such application;"],[2,"(B) has been a person of good moral character during such period;"],[2,"(C) has not been convicted of an offense under section 1182(a)(2), 1227(a)(2), or 1227(a)(3) of this title, subject to paragraph (5); and"],[2,"(D) establishes that removal would result in exceptional and extremely unusual hardship to the alien's spouse, parent, or child, who is a citizen of the United States or an alien lawfully admitted for permanent residence."],[0,"(2) Special rule for battered spouse or child"],[0,"(A) Authority"],[2,"The Attorney General may cancel removal of, and adjust to the status of an alien lawfully admitted for permanent residence, an alien who is inadmissible or deportable from the United States if the alien demonstrates that—"],[3,"(i)(I) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a United States citizen (or is the parent of a child of a United States citizen and the child has been battered or subjected to extreme cruelty by such citizen parent);"],[3,"(II) the alien has been battered or subjected to extreme cruelty by a spouse or parent who is or was a lawful permanent resident (or is the parent of a child of an alien who is or was a lawful permanent resident and the child has been battered or subjected to extreme cruelty by such permanent resident parent); or"],[3,"(III) the alien has been battered or subjected to extreme cruelty by a United States citizen or lawful permanent resident whom the alien intended to marry, but whose marriage is not legitimate because of that United States citizen's or lawful permanent resident's bigamy;"],[3,"(ii) the alien has been physically present in the United States for a continuous period of not less than 3 years immediately preceding the date of such application, and the issuance of a charging document for removal proceedings shall not toll the 3-year period of continuous physical presence in the United States;"],[3,"(iii) the alien has been a person of good moral character during such period, subject to the provisions of subparagraph (C);"],[3,"(iv) the alien is not inadmissible under paragraph (2) or (3) of section 1182(a) of this title, is not deportable under paragraphs (1)(G) or (2) through (4) of section 1227(a) of this title, subject to paragraph (5), and has not been convicted of an aggravated felony; and"],[3,"(v) the removal would result in extreme hardship to the alien, the alien's child, or the alien's parent."],[0,"(B) Physical presence"],[2,"Notwithstanding subsection (d)(2), for purposes of subparagraph (A)(ii) or for purposes of section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), an alien shall not be considered to have failed to maintain continuous physical presence by reason of an absence if the alien demonstrates a connection between the absence and the battering or extreme cruelty perpetrated against the alien. No absence or portion of an absence connected to the battering or extreme cruelty shall count toward the 90-day or 180-day limits established in subsection (d)(2). If any absence or aggregate absences exceed 180 days, the absences or portions of the absences will not be considered to break the period of continuous presence. Any such period of time excluded from the 180-day limit shall be excluded in computing the time during which the alien has been physically present for purposes of the 3-year requirement set forth in this subparagraph, subparagraph (A)(ii), and section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(C) Good moral character"],[2,"Notwithstanding section 1101(f) of this title, an act or conviction that does not bar the Attorney General from granting relief under this paragraph by reason of subparagraph (A)(iv) shall not bar the Attorney General from finding the alien to be of good moral character under subparagraph (A)(iii) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996), if the Attorney General finds that the act or conviction was connected to the alien's having been battered or subjected to extreme cruelty and determines that a waiver is otherwise warranted."],[0,"(D) Credible evidence considered"],[2,"In acting on applications under this paragraph, the Attorney General shall consider any credible evidence relevant to the application. The determination of what evidence is credible and the weight to be given that evidence shall be within the sole discretion of the Attorney General."],[0,"(3) Recordation of date"],[1,"With respect to aliens who the Attorney General adjusts to the status of an alien lawfully admitted for permanent residence under paragraph (1) or (2), the Attorney General shall record the alien's lawful admission for permanent residence as of the date of the Attorney General's cancellation of removal under paragraph (1) or (2)."],[0,"(4) Children of battered aliens and parents of battered alien children"],[0,"(A) In general"],[2,"The Attorney General shall grant parole under section 1182(d)(5) of this title to any alien who is a—"],[3,"(i) child of an alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996); or"],[3,"(ii) parent of a child alien granted relief under section 1229b(b)(2) or 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996)."],[0,"(B) Duration of parole"],[2,"The grant of parole shall extend from the time of the grant of relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to the time the application for adjustment of status filed by aliens covered under this paragraph has been finally adjudicated. Applications for adjustment of status filed by aliens covered under this paragraph shall be treated as if the applicants were VAWA self-petitioners. Failure by the alien granted relief under subsection (b)(2) or section 1254(a)(3) of this title (as in effect before the title III–A effective date in section 309 of the Illegal Immigration Reform and Immigrant Responsibility Act of 1996) to exercise due diligence in filing a visa petition on behalf of an alien described in clause (i) or (ii) may result in revocation of parole."],[0,"(5) Application of domestic violence waiver authority"],[1,"The authority provided under section 1227(a)(7) of this title may apply under paragraphs (1)(B), (1)(C), and (2)(A)(iv) in a cancellation of removal and adjustment of status proceeding."],[0,"(6) Relatives of trafficking victims"],[0,"(A) In general"],[2,"Upon written request by a law enforcement official, the Secretary of Homeland Security may parole under section 1182(d)(5) of this title any alien who is a relative of an alien granted continued presence under section 7105(c)(3)(A) of title 22, if the relative—"],[3,"(i) was, on the date on which law enforcement applied for such continued presence—"],[4,"(I) in the case of an alien granted continued presence who is under 21 years of age, the spouse, child, parent, or unmarried sibling under 18 years of age, of the alien; or"],[4,"(II) in the case of an alien granted continued presence who is 21 years of age or older, the spouse or child of the alien; or"],[3,"(ii) is a parent or sibling of the alien who the requesting law enforcement official, in consultation with the Secretary of Homeland Security, as appropriate, determines to be in present danger of retaliation as a result of the alien's escape from the severe form of trafficking or cooperation with law enforcement, irrespective of age."],[0,"(B) Duration of parole"],[0,"(i) In general"],[3,"The Secretary may extend the parole granted under subparagraph (A) until the final adjudication of the application filed by the principal alien under section 1101(a)(15)(T)(ii) of this title."]],"more":true,"ed":"2025","src":"https://www.govinfo.gov/link/uscode/8/1229b?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1229b. Cancellation of removal; adjustment of status","tname":"Aliens and Nationality","by":{"0":"12, 13, 13"}},{"t":"usc","label":"8 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/8/1251","subs":["(a)(2)(A)(1994)"],"by":{"0":"23"}},{"t":"usc","label":"18 U.S.C. § 371","url":"https://www.law.cornell.edu/uscode/text/18/371","stext":{"head":"§371. Conspiracy to commit offense or to defraud United States","paras":[[0,"If two or more persons conspire either to commit any offense against the United States, or to defraud the United States, or any agency thereof in any manner or for any purpose, and one or more of such persons do any act to effect the object of the conspiracy, each shall be fined under this title or imprisoned not more than five years, or both."],[0,"If, however, the offense, the commission of which is the object of the conspiracy, is a misdemeanor only, the punishment for such conspiracy shall not exceed the maximum punishment provided for such misdemeanor."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/371?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§371. Conspiracy to commit offense or to defraud United States","tname":"Crimes and Criminal Procedure","by":{"0":"5, 23"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"18, 19"}},{"t":"usc","label":"18 U.S.C. § 1962","url":"https://www.law.cornell.edu/uscode/text/18/1962","subs":["(c)"],"by":{"0":"18"}}]};